import string

def is_pangram(sentence):
    if not isinstance(sentence, str):
        return False
    alphabet = set(string.ascii_lowercase)
    letters = {ch.lower() for ch in sentence if ch.isalpha() and ch.isascii()}
    return alphabet.issubset(letters)
